#include "rx.h"
using namespace std;const int N=304,W=19;vector<int>a[N];mt19937 rng((unsigned)PI("prSeed"));struct Cand{string g;int av,hs,ex,re,ch;double cost,power,heat,cool;int seed;};vector<Cand>pool;long long generated=0,screened=0;double budget=PR.budget;int sim_steps=M.simSteps;bool expiry_test=false;
int core(char c){return c=='1'?1:c=='2'?2:c=='4'?4:0;}
bool sim(Cand c,int method,int fault,ostream*trace=nullptr){string g=c.g;array<double,N>h{},cap{};array<int,128>n{};for(char v:g)n[v]++;double p=n['P'],k=n['K'];double rate=M.rate0*(M.bEx+c.ex)*2*(1+M.capBoost*k),vr=M.vr0*(1+M.ventBoost*(M.bAv+c.av)*k),vc=M.vc0*(1+M.sinkBoost*(M.bHs+c.hs)*p),ec=M.ec0*(M.bEx+c.ex)*(1+M.reBoost*(M.bRe+c.re)*p),hc=M.hullPer*p;for(int i=0;i<N;i++)cap[i]=g[i]=='E'?ec:g[i]=='V'?vc:g[i]=='C'?M.ccap:g[i]=='K'?M.kcap:0;
 double hull=0,mE=0,mV=0,mC=0,mH=0,baseC=0;int branches=0;for(int i=0;i<N;i++)if(g[i]=='O')for(int j:a[i])if(cap[j]>0)branches++;const int ft=M.faultT;
 for(int t=0;t<sim_steps;t++){
 for(int i=0;i<N;i++)if(int co=core(g[i])){if(expiry_test&&t>=M.expStart&&t<M.expEnd)continue;int pulse=co==1?1:co==2?4:12;for(int j:a[i])pulse+=core(g[j]);double q=pulse*pulse*M.fuelHeat/co;int sinks=0;for(int j:a[i])sinks+=cap[j]>0;if(sinks)for(int j:a[i]){if(cap[j]>0)h[j]+=q/sinks;}if(!sinks)hull+=q;}
 for(int pass=0;pass<(method?2:1);pass++)for(int i=0;i<N;i++)if(g[i]=='E'){for(int jj=0;jj<(int)a[i].size();jj++){int j=a[i][method?a[i].size()-1-jj:jj];if(cap[j]<=0)continue;double delta=(h[i]+h[j])/(cap[i]+cap[j])*cap[j]-h[j];double q=clamp(delta,-rate,rate);q=clamp(q,-h[j],h[i]);h[j]+=q;h[i]-=q;}}
 double flow=min(hull,branches*rate);if(fault==1&&t>=ft&&t<ft+M.outFault)flow=0;hull-=flow;for(int i=0;i<N;i++)if(g[i]=='O')for(int j:a[i])if(cap[j]>0)h[j]+=flow/branches;
 for(int i=0;i<N;i++)if(g[i]=='V')h[i]=max(0.,h[i]-((fault==2&&t>=ft&&t<ft+M.ventFault)?0:vr));
 for(int i=0;i<N;i++)if(g[i]=='I')for(int j:a[i]){double q=min(rate,h[j]);h[j]-=q;hull+=q;}
 if(t==ft-1){for(int i=0;i<N;i++)if(g[i]=='C')baseC+=h[i];}
 if(hull>=hc){if(c.seed<0)cerr<<"hull fail "<<t<<"\n";return false;}for(int i=0;i<N;i++)if(cap[i]>0&&h[i]>=cap[i]){if(c.seed<0)cerr<<"fail "<<g[i]<<" at "<<t<<" ratio "<<h[i]/cap[i]<<" fault "<<fault<<"\n";return false;}
 if(t>=ft-1){for(int i=0;i<N;i++){if(g[i]=='E')mE=max(mE,h[i]/cap[i]);if(g[i]=='V')mV=max(mV,h[i]/cap[i]);if(g[i]=='C')mC=max(mC,h[i]/cap[i]);}mH=max(mH,hull/hc);}
 hull=max(0.,hull-hc*M.drain);
 }
 if(trace)*trace<<method<<","<<fault<<","<<mE<<","<<mV<<","<<mC<<","<<mH<<","<<baseC<<"\n";return true;
}
int main(int argc,char**argv){long long loops=PI("prLoops");int maxF=max(1,(int)PI("prMaxF")),pMin=(int)PI("prPmin"),pRange=max(1,(int)PI("prPrange")),maxTested=(int)PI("prTested");double coolM=P("prCoolM"),hullM=P("prHullM"),ventF=P("prVentF");rng.seed((unsigned)PI("prSeed"));for(int i=0;i<N;i++){if(i%W)a[i].push_back(i-1);if(i%W<18)a[i].push_back(i+1);if(i>=W)a[i].push_back(i-W);if(i+W<N)a[i].push_back(i+W);}for(long long z=0;z<loops;z++){if(z&&z%200000==0)cerr<<"попыток "<<z<<" прошли отбор "<<screened<<"\n";generated++;int bw=6+2*(rng()%7),bh=4*(1+rng()%4);if(bw*bh>250)continue;string g(N,'K');for(int y=0;y<bh;y++)for(int x=0;x<bw;x++){char c='K';if(y%2==0)c=x%2?'V':'E';else if(y%4==1)c=x%2?'P':'O';g[y*W+x]=c;}
 if(z%2){g.assign(N,'K');for(int yy=2;yy<16;yy+=5)for(int xx=2;xx<19;xx+=5){if(xx+2>=19||yy+2>=16||rng()%12==0)continue;int i=yy*19+xx;g[i]='O';for(int j:a[i])g[j]='E';for(int dx:{-1,1})for(int dy:{-1,1})g[i+dx+dy*19]='V';for(auto [dx,dy]:vector<pair<int,int>>{{2,0},{-2,0},{0,2},{0,-2}})g[i+dx+dy*19]=(rng()%100<15?'C':'V');}}
 int nFuel=1+rng()%maxF;int wantC=(z%2)?0:rng()%21;for(int i=0;i<304&&wantC;i++)if(g[i]=='K'&&i/19<bh&&i%19<bw&&i/19%4==3&&i%19%2==0&&rng()%2){g[i]='C';wantC--;}
 bool feed=(z/2)%2;for(int f=0;f<nFuel;f++){bool placed=false;for(int tries=0;tries<60;tries++){int i=rng()%N;bool ok=g[i]=='K';if(feed&&f==0){int x=i%19,y=i/19;if(!x||x==18||!y||y==15)continue;for(int yy=y-1;yy<=y+1;yy++)for(int xx=x-1;xx<=x+1;xx++)ok&=g[yy*19+xx]=='K';if(!ok)continue;g[i]='1';for(int j:a[i])g[j]='C';for(int dx:{-1,1})for(int dy:{-1,1})g[i+dx+dy*19]='I';}else{for(int j:a[i])ok&=g[j]=='K'||g[j]=='R';if(!ok)continue;int v=rng()%100;g[i]=v<90?'1':v<98?'2':'4';for(int j:a[i])g[j]='R';}placed=true;break;}if(!placed){g.clear();break;}}
 if(g.empty())continue;int targetP=pMin+rng()%pRange,pc=(int)count(g.begin(),g.end(),'P');for(int i=N-1;i>=0&&pc<targetP;i--)if(g[i]=='K'){g[i]='P';pc++;}
 array<int,128>n{};for(char c:g)n[c]++;int av=rng()%2,hs=rng()%2,ex=rng()%2,re=rng()%2,ch=rng()%2;double cost=PR.fuel(n)+PR.upgrades(av,hs,ex,re,ch)+PR.parts(n);if(cost>budget)continue;
 double H=0,P=0;for(int i=0;i<N;i++)if(int co=core(g[i])){int pulse=co==1?1:co==2?4:12,r=0;for(int j:a[i]){pulse+=core(g[j]);r+=g[j]=='R';}H+=pulse*pulse*M.fuelHeat/co;P+=pulse*M.fuelPow*(1+M.refl*r);}
 double cooling=n['V']*M.vr0*(1+M.ventBoost*(M.bAv+av)*n['K']);if(cooling<coolM*H||pc*M.hullPer<hullM*H||H/n['V']>ventF*M.vc0*(1+M.sinkBoost*(M.bHs+hs)*pc))continue;
 // Feed cell keeps heat in hull; inlet capacity must clear every coolant branch.
 double rate=M.rate0*(M.bEx+ex)*2*(1+M.capBoost*n['K']);if(feed&&2*rate<M.fuelHeat/4)continue;
 double held=feed?M.fuelHeat-pc*M.hullPer*M.drain:0.;if(held>0)P*=M.boost(held);
 double sales=M.sales(n['K']);P=min(P,sales);screened++;Cand c{g,av,hs,ex,re,ch,cost,P,H,cooling,(int)z};pool.push_back(c);
 }
 cerr<<"сортировка "<<pool.size()<<" кандидатов, симуляция...\n";
 sort(pool.begin(),pool.end(),[](const Cand&a,const Cand&b){double x=a.power*(M.bCh+a.ch),y=b.power*(M.bCh+b.ch);if(int(x/100)!=int(y/100))return int(x/100)>int(y/100);double ax=count(a.g.begin(),a.g.end(),'P')*(1+.1*a.hs)*(1+.1*a.re),bx=count(b.g.begin(),b.g.end(),'P')*(1+.1*b.hs)*(1+.1*b.re);return ax==bx?a.cost<b.cost:ax>bx;});ofstream stats("search-stats.txt");stats<<"generated="<<generated<<" screened="<<screened<<"\n";int tested=0,passed=0;double best=0;ofstream trace("tests.csv");trace<<"method,fault,max_E_fraction,max_V_fraction,max_C_fraction,max_hull_fraction,steady_C_B\n";for(auto c:pool){if(c.power*(M.bCh+c.ch)<best)break;if(tested++>=maxTested)break;if(tested==1){auto debug=c;debug.seed=-1;for(int ff=0;ff<3;ff++)sim(debug,0,ff);}bool ok=true;for(int m=0;m<2;m++)for(int f=0;f<3;f++)if(!sim(c,m,f)){ok=false;break;}if(!ok)continue;passed++;best=c.power*(M.bCh+c.ch);ofstream out("best.txt");out<<setprecision(12)<<c.power<<" "<<c.heat<<" "<<c.cool<<" "<<c.cost<<" "<<c.av<<" "<<c.hs<<" "<<c.ex<<" "<<c.re<<" "<<c.ch<<" "<<c.seed<<"\n";for(int y=0;y<16;y++)out<<c.g.substr(y*19,19)<<"\n";for(int m=0;m<2;m++)for(int f=0;f<3;f++)sim(c,m,f,&trace);cerr<<"найдено: мощность "<<c.power<<" цена "<<c.cost<<" -> best.txt\n";break;}stats<<"simulated_candidates="<<tested<<" passing="<<passed<<"\n";cerr<<"done generated "<<generated<<" screened "<<screened<<" tested "<<tested<<" passed "<<passed<<"\n";return 0;}
